from html.parser import HTMLParser
from pathlib import Path
import json

class ReviewParser(HTMLParser):
    def __init__(self):
        super().__init__(); self.sections=[]; self.headings=[]; self._heading=False; self.resources=[]
    def handle_starttag(self, tag, attrs):
        attrs=dict(attrs)
        if tag=='section': self.sections.append(attrs.get('class'))
        if tag=='h3': self._heading=True
        for key in ('src','href'):
            if key in attrs: self.resources.append(attrs[key])
    def handle_endtag(self, tag):
        if tag=='h3': self._heading=False
    def handle_data(self, data):
        if self._heading: self.headings.append(data)

p=ReviewParser(); p.feed(Path('planning/comparison.html').read_text())
options=json.loads(Path('layouts.json').read_text())
cards=json.loads(Path('cards.json').read_text())
assert p.sections == [x['id'] for x in options], p.sections
assert p.headings == [x['title'] for x in cards] * len(options), p.headings
assert not p.resources, 'Review must be self-contained, without external resources'
print('PASS: both layouts contain every workshop card and require no external resources. Browser appearance remains a separate observation.')

